const circularShift = (x, shift) => {
    const digits = x.toString();
    const numDigits = digits.length;

    if (shift > numDigits) {
        return digits.split('').reverse().join('');
    }

    if (shift === numDigits) {
        return digits;
    }

    const effectiveShift = shift % numDigits;
    const shifted = digits.slice(-effectiveShift) + digits.slice(0, -effectiveShift);

    return shifted;
};

