const willItFly = (q, w) => {
    // Check if the array is palindromic (balanced)
    const isBalanced = (arr) => {
        for (let i = 0; i < Math.floor(arr.length / 2); i++) {
            if (arr[i] !== arr[arr.length - 1 - i]) {
                return false;
            }
        }
        return true;
    };

    // Check if sum is less than or equal to maximum weight
    const sum = q.reduce((acc, val) => acc + val, 0);

    // Return true if balanced and sum is within weight limit
    return isBalanced(q) && sum <= w;
};

