const isMultiplyPrime = (a) => {
    if (a < 2) return false;

    const isPrime = (num) => {
        if (num < 2) return false;
        if (num === 2) return true;
        if (num % 2 === 0) return false;
        for (let i = 3; i <= Math.sqrt(num); i += 2) {
            if (num % i === 0) return false;
        }
        return true;
    };

    let count = 0;
    let product = 1;

    for (let i = 2; i <= a; i++) {
        if (isPrime(i) && a % i === 0) {
            count++;
            product *= i;
            while (a % i === 0) {
                a /= i;
            }
        }
    }

    return count === 3 && product === a;
};

